import React, { useEffect, useState } from "react";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import { ShieldAlert, Bell, AlertTriangle, Search, X } from "lucide-react";
import { getTransactions, getUserStatus } from "./api";

function App() {
  const [transactions, setTransactions] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [userHistory, setUserHistory] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [alerts, setAlerts] = useState([]);

  useEffect(() => {
    const fetchData = () => {
      getTransactions()
        .then((res) => {
          if (res && res.data) {
            setTransactions(res.data);
          }
        })
        .catch(() => console.log("API error"));
    };

    fetchData(); // İlk çalıştırma
    const interval = setInterval(fetchData, 3000); // 3 saniyede bir güncelle

    return () => clearInterval(interval);
const eventSource = new EventSource('http://localhost:8000/stream-alerts');

  eventSource.addEventListener('fraud_alert', (event) => {
    const newAlert = JSON.parse(event.data);
    setAlerts((prevAlerts) => [newAlert, ...prevAlerts]);
  });

  return () => {
    eventSource.close();
  };
}, []);




  const openUserDetail = (userId) => {
    if (userId) {
      getUserStatus(userId)
        .then((res) => {
          setUserHistory(res.data);
          setSelectedUser(userId);
          setShowModal(true);
        })
        .catch((err) => console.log("User history error", err));
    }
  };

  const fraudCount = transactions.filter((t) => t.status === "FRAUD").length;
  const fraudRate = transactions.length
    ? ((fraudCount / transactions.length) * 100).toFixed(1)
    : 0;

  const totalTransactions = transactions.length;
  const activeAlerts = transactions.filter((t) => t.status === "FRAUD").length;
  const avgRisk = 45; // Statik varsayılan değer

  const chartData = transactions.slice(-20).map((t) => ({
    time: new Date(t.timestamp).toLocaleTimeString(),
    fraud: t.status === "FRAUD" ? 1 : 0,
    amount: t.amount,
  }));

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-100 font-mono selection:bg-blue-900/50">
      {/* Header */}
      <header className="border-b border-slate-800 bg-[#0f172a]/90 backdrop-blur-sm sticky top-0 z-30 px-6 py-4 flex justify-between items-center">
        <div className="flex items-center space-x-3">
          <ShieldAlert className="w-6 h-6 text-blue-500 animate-pulse" />
          <h1 className="text-xl font-bold tracking-tight text-white">
            SENTINEL | Anomali Tespit Platformu
          </h1>
        </div>
        <div className="flex items-center space-x-4 text-sm text-slate-400">
          <span className="flex items-center">
            <span className="w-2 h-2 bg-green-500 rounded-full mr-2 animate-ping"></span>
            Sistem Aktif
          </span>
          <span className="bg-slate-800 px-3 py-1 rounded-full text-slate-200 border border-slate-700 text-xs">
            Production
          </span>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-8">
        {/* KPI Section */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          <KPI label="Toplam İşlem" value={totalTransactions} color="text-blue-400" />
          <KPI label="Fraud Oranı" value={`%${fraudRate}`} color="text-red-400" />
          <KPI label="Aktif Alarmlar" value={activeAlerts} color="text-yellow-400" />
          <KPI label="Ortalama Risk Skoru" value={avgRisk} color="text-indigo-400" />
        </div>

        <div className="grid grid-cols-12 gap-8">
          {/* Left Column: Real-Time Stream */}
          <div className="col-span-12 lg:col-span-8 space-y-6">
            <div className="bg-[#0f172a] border border-slate-800 rounded-xl p-6 shadow-xl">
              <h2 className="text-lg font-semibold text-white mb-4 flex items-center">
                <AlertTriangle className="w-5 h-5 mr-2 text-blue-400" />
                Canlı İşlem Akışı
              </h2>
              <div className="overflow-x-auto max-h-[450px] overflow-y-auto border border-slate-800 rounded-lg divide-y divide-slate-800">
                {transactions.length === 0 ? (
                  <p className="p-6 text-center text-slate-500">İşlem bekleniyor...</p>
                ) : (
                  <table className="w-full text-left text-sm">
                    <thead className="bg-slate-900 text-slate-400 sticky top-0">
                      <tr>
                        <th className="p-4">Kullanıcı ID</th>
                        <th className="p-4">Tutar</th>
                        <th className="p-4">Durum</th>
                        <th className="p-4">Zaman</th>
                        <th className="p-4">İşlem</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800 text-slate-300">
                      {transactions.map((t, idx) => (
                        <tr key={idx} className="hover:bg-slate-800/40 transition-colors">
                          <td className="p-4 font-mono text-indigo-400">{t.user_id}</td>
                          <td className="p-4 text-white font-semibold">{t.amount} TL</td>
                          <td className="p-4">
                            <StatusBadge status={t.status} />
                          </td>
                          <td className="p-4 text-slate-500">
                            {new Date(t.timestamp).toLocaleTimeString()}
                          </td>
                          <td className="p-4">
                            <button
                              onClick={() => openUserDetail(t.user_id)}
                              className="text-blue-400 hover:text-blue-300 transition flex items-center gap-1 text-xs"
                            >
                              <Search className="w-4 h-4" />
                              Detay
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>
            </div>
          </div>

          {/* Right Column: Analytics & Alerts */}
          <div className="col-span-12 lg:col-span-4 space-y-6">
            {/* Analytics */}
            <div className="bg-[#0f172a] border border-slate-800 rounded-xl p-6 shadow-xl">
              <h2 className="text-lg font-semibold text-white mb-4 flex items-center">
                <ShieldAlert className="w-5 h-5 mr-2 text-indigo-400" />
                Fraud Değişimi
              </h2>
              <div className="h-[200px]">
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={chartData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                    <XAxis dataKey="time" stroke="#64748b" />
                    <YAxis stroke="#64748b" />
                    <Tooltip
                      contentStyle={{ backgroundColor: "#0f172a", borderColor: "#334155" }}
                      labelStyle={{ color: "#fff" }}
                    />
                    <Line
                      type="stepAfter"
                      dataKey="fraud"
                      stroke="#ef4444"
                      strokeWidth={2}
                      dot={{ fill: "#ef4444" }}
                    />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </div>

            {/* Real-time Alert Panel */}
            <div className="bg-[#0f172a] border border-slate-800 rounded-xl p-6 shadow-xl">
              <h2 className="text-lg font-semibold text-white mb-4 flex items-center">
                <Bell className="w-5 h-5 mr-2 text-red-500" />
                Anlık Uyarı Paneli
              </h2>
              <div className="space-y-3 max-h-[220px] overflow-y-auto">
                {transactions
                  .filter((t) => t.status === "FRAUD")
                  .slice(0, 5)
                  .map((t, idx) => (
                    <div
                      key={idx}
                      className="bg-red-950/50 border border-red-900/40 p-3 rounded-lg flex justify-between items-center text-red-400 animate-pulse text-xs"
                    >
                      <div>
                        <span className="font-semibold">Kullanıcı: </span>
                        {t.user_id} - FRAUD!
                      </div>
                      <div className="text-[10px] text-red-600">
                        {new Date(t.timestamp).toLocaleTimeString()}
                      </div>
                    </div>
                  ))}
                {transactions.filter((t) => t.status === "FRAUD").length === 0 && (
                  <p className="text-center text-slate-500 text-xs py-8">
                    Aktif alarm bulunmuyor.
                  </p>
                )}
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* Modal - Deep Dive Panel */}
      {showModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 rounded-xl max-w-2xl w-full p-6 shadow-2xl relative">
            <button
              onClick={() => setShowModal(false)}
              className="text-slate-400 hover:text-white absolute top-4 right-4 transition"
            >
              <X className="w-6 h-6" />
            </button>

            <h3 className="text-xl font-bold text-white mb-4">
              Kullanıcı Detay Analizi: #{selectedUser}
            </h3>

            {userHistory ? (
              <div className="space-y-6">
                <div className="grid grid-cols-3 gap-4">
                  <div className="bg-slate-800/30 border border-slate-700/40 p-4 rounded-lg">
                    <p className="text-xs text-slate-400 uppercase tracking-wider">
                      Toplam İşlem
                    </p>
                    <p className="text-2xl font-bold text-white mt-1">
                      {userHistory.total_transactions || 5}
                    </p>
                  </div>
                  <div className="bg-slate-800/30 border border-slate-700/40 p-4 rounded-lg">
                    <p className="text-xs text-slate-400 uppercase tracking-wider">
                      Fraud Sayısı
                    </p>
                    <p className="text-2xl font-bold text-red-400 mt-1">
                      {userHistory.fraud_count || 1}
                    </p>
                  </div>
                  <div className="bg-slate-800/30 border border-slate-700/40 p-4 rounded-lg">
                    <p className="text-xs text-slate-400 uppercase tracking-wider">
                      Risk Skoru
                    </p>
                    <p className="text-2xl font-bold text-yellow-400 mt-1">
                      Yüksek
                    </p>
                  </div>
                </div>

                {/* AI Explanation */}
                <div className="bg-red-950/20 border border-red-900/30 p-4 rounded-lg">
                  <h4 className="text-sm font-bold text-red-400 mb-2">
                    🤖 AI Karar Motoru (AI Decision Engine)
                  </h4>
                  <p className="text-xs text-slate-300 leading-relaxed">
                    Kullanıcı #{selectedUser} için gerçekleştirilen işlem hızı veya
                    konum kuralı sınırlarını ihlal etti. Detaylı analiz sonucunda işlem
                    şüpheli olarak işaretlendi.
                  </p>
                </div>

                {/* Transaction Timeline History */}
                <div>
                  <h4 className="text-sm font-bold text-white mb-3">İşlem Geçmişi</h4>
                  <div className="space-y-2 max-h-[180px] overflow-y-auto pr-2">
                    {userHistory.transactions && userHistory.transactions.length > 0 ? (
                      userHistory.transactions.map((tx, idx) => (
                        <div
                          key={idx}
                          className="flex justify-between items-center bg-slate-800/40 px-4 py-3 rounded-lg border border-slate-700/30"
                        >
                          <span className="text-sm text-slate-400">
                            {new Date(tx.timestamp).toLocaleTimeString()}
                          </span>
                          <span className="text-sm font-semibold text-white">
                            {tx.amount} TL
                          </span>
                          <StatusBadge status={tx.status} />
                        </div>
                      ))
                    ) : (
                      <div className="flex justify-between items-center bg-slate-800/40 px-4 py-3 rounded-lg border border-slate-700/30">
                        <span className="text-sm text-slate-400">16:45:42</span>
                        <span className="text-sm font-semibold text-white">152.0 TL</span>
                        <StatusBadge status="FRAUD" />
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ) : (
              <p className="text-slate-400 text-center py-6">Veriler yükleniyor...</p>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

const KPI = ({ label, value, color = "text-blue-400" }) => {
  return (
    <div className="bg-[#0f172a] border border-slate-800/60 rounded-xl p-6 shadow-xl">
      <p className="text-xs text-slate-400 uppercase tracking-wider mb-1">{label}</p>
      <p className={`text-3xl font-bold ${color}`}>{value}</p>
    </div>
  );
};

const StatusBadge = ({ status }) => {
  const styles = {
    FRAUD:
      "text-red-400 bg-red-950/40 border border-red-900/40 px-2.5 py-0.5 rounded-full text-xs font-bold uppercase tracking-wider",
    APPROVED:
      "text-green-400 bg-green-950/40 border border-green-900/40 px-2.5 py-0.5 rounded-full text-xs font-bold uppercase tracking-wider",
  };

  return (
    <span className={styles[status] || styles.APPROVED}>
      {status === "FRAUD" ? "Şüpheli" : "Onaylandı"}
    </span>
  );
};

export default App;
